// Üretilen dosya: tool/ozgun/uret.py. Doğa · Memeliler ayrıntılı (kolay).
const ozNature6Kolay = <(String, String, List<String>, String)>[
  ('Memelilerde orta kulakta kaç tane kemikçik bulunur?', 'Üç', ['Bir', 'İki', 'Dört'], 'Memelilerin orta kulağında çekiç, örs ve üzengi olmak üzere üç kemikçik vardır; sürüngen ve kuşlarda yalnızca bir kemikçik bulunur.'),
  ('Göğüs boşluğunu karın boşluğundan ayıran ve soluk almada başlıca rol oynayan kaslı zar hangi omurgalı grubuna özgüdür?', 'Memeliler', ['Kuşlar', 'Sürüngenler', 'Kıkırdaklı balıklar'], 'Diyafram yalnız memelilerde bulunur; kasıldığında göğüs boşluğunu genişleterek akciğerlere hava girmesini sağlar.'),
  ('Memeliler sınıfı günümüzde genel olarak hangi üç büyük gruba ayrılır?', 'Monotremler, keseliler ve plasentalılar', ['Otçullar, etçiller ve hepçiller', 'Karasallar, sucullar ve uçanlar', 'Tek toynaklılar, çift toynaklılar ve etçiller'], 'Yaşayan memeliler yumurtlayan monotremler, gelişmemiş yavru doğurup çoğunlukla kesede büyüten keseliler ve iyi gelişmiş bir plasentası olan plasentalılar olarak üçe ayrılır.'),
  ('Ekidnelerin besininin büyük bölümünü oluşturan canlılar hangileridir?', 'Karıncalar ve termitler', ['Küçük balıklar ve kurbağalar', 'Olgun meyveler ve tohumlar', 'Kuş yumurtaları ve civcivler'], 'Kısa gagalı ekidne uzun yapışkan diliyle başta karınca ve termit olmak üzere küçük omurgasızlarla beslenir; dişi yoktur.'),
  ('Monotremler bugün yalnızca hangi bölgede doğal olarak yaşar?', 'Avustralya ve Yeni Gine', ['Güney Amerika ve Antiller', 'Madagaskar ve Komorlar', 'Güneydoğu Asya ve Borneo'], 'Ornitorenk Avustralya\'nın doğusunda, ekidneler ise Avustralya ve Yeni Gine\'de yaşar; başka hiçbir yerde doğal monotrem bulunmaz.'),
  ('Şeker planörünün (sugar glider) ağaçtan ağaca geçebilmesini sağlayan yapı hangisidir?', 'Ön ve arka bacakları arasında uzanan deri zarı', ['Yarasalarınki gibi uzamış parmaklar arasındaki kanat', 'Kuyruğundaki geniş kanatçık biçimli kıllar', 'Gövde yanlarındaki şişirilebilen hava keseleri'], 'Şeker planörü keseli bir memelidir; bacakları arasındaki deri zarını açarak süzülür. Kuzey yarım küredeki uçan sincaplara benzerliği yakınsak evrimdir.'),
  ('Kangurular yavaş hareket ederken beş ayaklı yürüyüş denen bir yöntem kullanır. Bu yürüyüşte beşinci destek noktası nedir?', 'Kuyruk', ['Alt çene', 'Kesedeki yavru', 'Göğüs kafesi'], 'Yavaş ilerleyen kanguru, ön ayakları ve güçlü kuyruğuyla yere dayanıp arka bacaklarını birlikte öne taşır; kuyruk burada beşinci bacak gibi itme sağlar.'),
  ('Afrika\'da geceleri termit tümseklerini güçlü pençeleriyle kazan, uzun kulaklı ve domuza benzeyen burunlu memeli hangisidir?', 'Yer domuzu (aardvark)', ['Pangolin (pullu karıncayiyen)', 'Okapi', 'Bal porsuğu'], 'Yer domuzu, Tubulidentata takımının yaşayan tek türüdür; yapışkan diliyle termit ve karınca toplar.'),
  ('Hortum gibi uzun ve oynak burnuyla tanınan fil sivri faresi (sengi) adını neden almıştır?', 'Uzun, hareketli burnu fil hortumunu andırdığı için', ['Fillerle aynı sürülerde yaşadığı için', 'Fil dışkısındaki tohumlarla beslendiği için', 'Fil kadar uzun yaşadığı için'], 'Sengilerin uzun burnu fil hortumunu andırır; ilginç olarak moleküler çalışmalar onları gerçekten de fillerle aynı büyük grupta (Afrotheria) toplar.'),
  ('Tembel hayvanlar dışkılamak için yaklaşık haftada bir ağaçtan yere iner. Bu davranışın bilinen olumsuz yanı nedir?', 'Yerde avcılara karşı savunmasız kalmaları', ['Ağaçların köklerini kurutmaları', 'Yerde enerji harcamadan dinlenmeleri', 'Kürklerindeki algleri tamamen kaybetmeleri'], 'Tembel hayvanlar yerde çok yavaş hareket eder; bu iniş sırasında jaguar gibi avcılara karşı en savunmasız oldukları zamandır.'),
  ('Afrika savan fili ile Asya filini kulaklarına bakarak ayırt etmek isteyen biri neye dikkat etmelidir?', 'Afrika filinin kulakları çok daha büyüktür', ['Asya filinin kulakları sivri uçludur ve dik durur', 'İki türün kulakları aynıdır, yalnız renkleri farklıdır', 'Afrika filinin kulakları kıllarla kaplıdır'], 'Afrika fillerinin kulakları Afrika kıtasının haritasını andıracak kadar büyüktür; Asya fillerinin kulakları daha küçük ve yuvarlaktır.'),
  ('Fillerin gebelik süresi yaklaşık ne kadardır?', 'Yaklaşık 22 ay', ['Yaklaşık 9 ay', 'Yaklaşık 15 ay', 'Yaklaşık dört yıl'], 'Fillerin gebeliği yaklaşık 22 ay sürer; bu, yaşayan kara memelileri arasında en uzun gebelik süresidir.'),
  ('Fillerin sık sık çamur ya da toz banyosu yapmasının başlıca yararı hangisidir?', 'Deriyi güneşe ve böcek ısırıklarına karşı korumak', ['Kulak kepçelerini sürtünmeye karşı aşınmaktan korumak', 'Hortumdaki kılları ve koku alıcılarını temizlemek', 'Fildişlerini parlatıp rakiplere göstermek'], 'Fil derisi kalın görünse de güneş yanığına ve parazitlere duyarlıdır; çamur katmanı serinletir, güneşi keser ve böceklere karşı bariyer oluşturur.'),
  ('Zürafalar uzun ve kavrayıcı dillerini en çok hangi besini toplamak için kullanır?', 'Dikenli akasya dallarındaki yaprakları', ['Yerdeki kuru otları ve tohumları', 'Göl kıyısındaki su bitkilerinin köklerini', 'Ağaç kabuğunun altındaki böcek larvalarını'], 'Zürafa yaklaşık yarım metreye ulaşan kavrayıcı diliyle dikenlerin arasından akasya yapraklarını sıyırır.'),
  ('Zürafaların su içmek için ön bacaklarını iki yana açıp eğilmek zorunda kalması onları hangi açıdan dezavantajlı kılar?', 'Avcılara karşı savunmasız kalırlar', ['Bu sırada kalp atışları tamamen durur', 'Bu sırada boyun omurları kolayca kırılabilir', 'Bu sırada dilleri güneşte kuruyup yaralanır'], 'Eğilip su içen zürafa çabuk doğrulup kaçamaz; bu nedenle su başında aslan gibi avcılara karşı en savunmasız anlarından birini yaşar.'),
  ('Kongo\'nun yağmur ormanlarında yaşayan ve Batı bilim dünyasınca ancak 20. yüzyılın başında tanınan çift toynaklı orman hayvanı hangisidir?', 'Okapi', ['Bongo', 'Tapir', 'Sitatunga'], 'Okapi bilim dünyasına 1901\'de tanıtılmıştır; utangaç yapısı ve sık orman yaşamı nedeniyle uzun süre bilinmemiştir.'),
  ('Develer yürürken aynı taraftaki ön ve arka bacağını birlikte ileri atar. Bu yürüyüş biçimine ne ad verilir?', 'Yorga yürüyüşü', ['Dörtnala koşu', 'Tırıs yürüyüşü', 'Eşkin sıçrayışı'], 'Yorgada aynı yandaki iki bacak birlikte hareket eder; develer, zürafalar ve bazı at ırkları bu yürüyüşü kullanır. Tırısta ise çapraz bacaklar birlikte hareket eder.'),
  ('Lama ile alpaka arasındaki tipik kullanım farkı hangisidir?', 'Lama daha çok yük taşımak, alpaka yünü için yetiştirilir', ['Lama sütü için, alpaka ise yalnızca eti için yetiştirilir', 'Lama yalnız avcılıkta, alpaka ise tarla sürmede kullanılır', 'Lama koşu yarışlarında, alpaka binicilikte kullanılır'], 'Daha iri olan lama And Dağları\'nda yük hayvanı olarak, daha küçük alpaka ise yumuşak lifi için yetiştirilir.'),
  ('Develerin ve lamaların rahatsız edildiklerinde \'tükürdükleri\' madde aslında çoğunlukla nedir?', 'Mideden gelen yarı sindirilmiş besin', ['Yalnızca ağız bezlerinin ürettiği salya', 'Burun bezlerinin ürettiği zehirli salgı', 'Hörgüçten gelen erimiş yağ ve su karışımı'], 'Devegiller öfkelendiğinde midelerindeki yarı sindirilmiş içeriği salya ile karıştırarak püskürtür; bu, kötü kokulu bir savunma ve uyarı davranışıdır.'),
  ('\'Bahşiş atın dişine bakılmaz\' sözü, atın hangi özelliğinin dişlerden anlaşılabildiğine dayanır?', 'Yaşının', ['Cinsiyetinin', 'Rengi', 'Hızının'], 'Atın kesici dişlerindeki aşınma ve biçim değişiklikleri yaşla birlikte belirli bir düzen izler; bu yüzden deneyimli kişiler atın yaşını dişlerinden tahmin eder.'),
  ('Atın gözlerinin başın iki yanında olması ona hangi avantajı sağlar?', 'Çevresini neredeyse tümüyle görebilmesi', ['Uzaklığı iki gözüyle çok keskin tahmin etmesi', 'Karanlıkta renkleri ayırt etmesi', 'Burnunun önünü net görmesi'], 'Yandaki gözler av hayvanına çok geniş bir görüş alanı sağlar; buna karşılık burnunun hemen önünde ve tam arkasında kör noktalar oluşur.'),
  ('Gergedanların hangi duyusu diğerlerine göre zayıftır?', 'Görme', ['Koku alma', 'İşitme', 'Dokunma'], 'Gergedanların görme yeteneği zayıftır; buna karşılık koku alma ve işitme duyuları çok gelişmiştir. Bu nedenle yakındaki kıpırtısız bir insanı çoğu zaman fark etmezler.'),
  ('Su aygırlarının dışkılarını kuyruklarını pervane gibi döndürerek etrafa saçmasının bilinen işlevi nedir?', 'Bölge işaretlemek', ['Suyu ısıtmak', 'Avcıları uzaklaştırmak için zehir yaymak', 'Yavruları beslemek'], 'Erkek su aygırları dışkıyı kuyruk sallayarak yayar; bu davranış koku yoluyla bölge sınırlarını ve baskınlığı bildirir.'),
  ('Batı Afrika ormanlarında yaşayan, büyük su aygırından çok daha küçük ve daha çok karada yaşayan tür hangisidir?', 'Cüce su aygırı', ['Okapi', 'Kırmızı orman domuzu', 'Babirusa'], 'Cüce su aygırı Liberya ve çevresindeki ormanlarda yaşar; büyük akrabasına göre daha yalnız ve orman tabanına bağlıdır.'),
  ('Domuzların sıcak havada çamura yuvarlanmasının başlıca nedeni hangisidir?', 'Ter bezlerinin çok az olması', ['Kirli yaşamayı sevmeleri', 'Çamurdaki tuzu yalayabilmeleri', 'Derilerinin kalın kıllarla örtülü olması'], 'Domuzların işlevsel ter bezi çok azdır; ıslak çamur buharlaşarak vücudu serinletir ve güneşe karşı koruma sağlar.'),
  ('Yaban domuzu yavrularının açık renkli boyuna çizgilerle doğmasının en olası işlevi nedir?', 'Orman altındaki gölgelerde kamufle olmak', ['Sürü içinde liderini ve annesini kolayca bulmak', 'Erkek ve dişiyi ayırt etmek', 'Isıyı daha iyi emmek'], 'Çizgili desen yavruyu yaprak döküntüsü ve gölgeler arasında gizler; yavrular büyüdükçe bu çizgiler kaybolur.'),
  ('Keçilerin göz bebeklerinin yatay dikdörtgen biçimli olması onlara ne kazandırır?', 'Ufku boyunca geniş bir panoramik görüş', ['Gece karanlığında renkleri ayırt edebilme', 'Çok uzaktaki nesneleri büyüterek görme', 'Su altında bile net görebilme'], 'Yatay göz bebeği, otlayan av hayvanlarının çevredeki avcıyı fark etmesini kolaylaştıran geniş ve yere paralel bir görüş alanı sağlar.'),
  ('Yaşayan en büyük geyik türü olan, kürek biçimli geniş boynuzlu ve su bitkileri için göllere dalabilen hayvan hangisidir?', 'Sığın', ['Kızıl geyik', 'Ren geyiği', 'Alageyik'], 'Sığın (Alces alces) yaşayan en büyük geyiktir; iyi bir yüzücüdür ve yazın sodyumca zengin su bitkileriyle beslenmek için suya girer.'),
  ('Kızıl geyik erkeklerinin sonbaharda çiftleşme döneminde yüksek sesle böğürmesinin işlevlerinden biri hangisidir?', 'Rakiplere güç gösterip dişileri çekmek', ['Sürüyü kurtlardan uzaklaştırıp korumak', 'Yavrulara emzirme zamanını bildirmek', 'Kış göçünün başladığını sürüye duyurmak'], 'Böğürme sıklığı ve gücü erkeğin kondisyonunu yansıtır; erkekler bu seslerle rakiplerini değerlendirir ve dişiler de bu seslerden etkilenir.'),
  ('Benekli kürkü ve yetişkin erkeklerdeki kürek biçimli geniş boynuzlarıyla tanınan geyik türü hangisidir?', 'Alageyik', ['Karaca', 'Kızıl geyik', 'Muntjak'], 'Alageyik (Dama dama) yazın beyaz benekli kürkü ve erkeklerdeki yassı, kürek biçimli boynuzlarıyla diğer geyiklerden kolayca ayrılır.'),
  ('Geyik annesi yeni doğan yavrusunu ilk haftalarda çoğunlukla otların arasında yalnız bırakıp yalnız emzirmek için yanına gelir. Bu stratejinin yararı nedir?', 'Avcıların yavruyu bulmasını zorlaştırmak', ['Yavrunun kendi besinini erkenden öğrenmesi', 'Annenin sürüdeki başka yavrulara da bakabilmesi', 'Yavrunun soğuğa ve yağmura erkenden alışması'], 'Bu \'saklanan yavru\' stratejisinde hareketsiz ve neredeyse kokusuz yavru gizli kalır; anne sık sık gelirse kokusuyla avcıları yavruya çekebilir.'),
  ('Bataklık ve sazlıklarda yaşayan sitatunga antilobunun çok uzun ve yayılabilen toynaklarının işlevi nedir?', 'Yumuşak çamura batmadan yürümek', ['Ormanda ağaç gövdelerine tırmanmak', 'Kumu hızla kazıp yuva açmak', 'Avcılara sert tekmeler atmak'], 'Sitatunganın uzun ve iki yana açılabilen toynakları ağırlığı geniş alana yayar; böylece bataklıkta batmadan ilerleyebilir.'),
  ('Kediler ve köpekler yürürken ayaklarının hangi kısmına basar?', 'Parmaklarının üzerine', ['Bütün tabanlarına', 'Tırnak uçlarına', 'Bileklerinin üstüne'], 'Kedi ve köpekler parmak üstünde yürüyen (dijitigrad) hayvanlardır; topuk yerden yüksekte kalır, bu da adımı uzatır ve hızı artırır.'),
  ('Afrika yaban köpeklerinin (likaon) avlanma biçimini en iyi anlatan seçenek hangisidir?', 'Sürüce uzun süre kovalayarak', ['Pusuda bekleyip tek bir sıçrayışla', 'Ağaç üstünden avın üzerine atlayarak', 'Avı suya sürükleyip orada boğarak'], 'Afrika yaban köpekleri sürü hâlinde, avını kilometrelerce kovalayarak yorar; büyük memeliler arasında en yüksek av başarısına sahip avcılardandır.'),
  ('\'Kara panter\' olarak bilinen hayvan hangisidir?', 'Koyu renkli leopar ya da jaguar', ['Asya\'ya özgü ayrı bir kedi türü', 'Siyah kıllı bir Amerika puması', 'Kaplan ile aslan arasındaki melez'], 'Kara panter ayrı bir tür değildir; koyu pigment fazlalığı (melanizm) gösteren leopar ya da jaguardır. Yakından bakılınca rozetleri yine seçilebilir.'),
  ('Kuzey Amerika\'nın güneyinden Güney Amerika\'nın güneyine kadar yayılan ve dağ aslanı, kuguar gibi pek çok adı olan kedi hangisidir?', 'Puma', ['Jaguar', 'Ocelot', 'Vaşak'], 'Puma Batı yarım kürede en geniş yayılışa sahip kara memelilerindendir; büyük olmasına rağmen kükreyemez, küçük kediler gibi ses çıkarır.'),
  ('Çitanın yüzündeki gözlerinin iç köşesinden ağzına doğru inen siyah \'gözyaşı çizgilerinin\' olası işlevi hangisidir?', 'Güneşin parlamasını azaltmak', ['Daha iri avcıları korkutmak', 'Burnunun çevresini soğutmak', 'Yavrularının onu tanımasını sağlamak'], 'Gündüz avlanan çitada bu koyu çizgilerin, futbolcuların göz altına sürdüğü siyah boya gibi, güneş ışığının yansımasını azalttığı düşünülür.'),
  ('Çita kovalama sırasında keskin dönüşler yaparken dengesini korumak için hangi vücut parçasını dümen gibi kullanır?', 'Kuyruğunu', ['Kulak kepçelerini', 'Yüzündeki bıyıklarını', 'Ön pençelerini'], 'Çitanın uzun ve kaslı kuyruğu, yüksek hızda yön değiştirirken karşı ağırlık görevi yaparak dönüşlerde dengeyi sağlar.'),
  ('Erkek aslan ile dişi kaplanın çiftleşmesinden doğan ve genellikle her iki ebeveynden de iri olan melez hangisidir?', 'Liger', ['Tigon', 'Leopon', 'Jaglion'], 'Liger erkek aslan ile dişi kaplanın; tigon ise erkek kaplan ile dişi aslanın melezidir. Bu melezler doğada değil, esaret altında ortaya çıkar.'),
  ('Bozayıyı diğer ayılardan ayırmaya yarayan, omuzlarının üstündeki belirgin kambur aslında nedir?', 'Kazmada kullanılan güçlü kas kütlesi', ['Kış dinlenmesi için depolanan su', 'Omurlardan yükselen kemik bir çıkıntı', 'Devenin hörgücü gibi yağ dolu bir kese'], 'Bozayının omuz kamburu, ön bacaklarla toprak kazmayı ve kök sökmeyi sağlayan güçlü kaslardan oluşur.'),
  ('Yaşayan ayıların en küçüğü olan, Güneydoğu Asya ormanlarında yaşayan ve çok uzun diliyle bal ve böcek yiyen tür hangisidir?', 'Güneş ayısı', ['Gözlüklü ayı', 'Asya kara ayısı', 'Tembel ayı'], 'Güneş ayısı en küçük ayı türüdür; göğsündeki altın renkli hilal biçimli leke ve uzun diliyle tanınır.'),
  ('Kış dinlenmesindeki dişi bozayının yavruları doğduğunda nasıldır?', 'Çok küçük, kör ve az kıllı', ['Annesinin yaklaşık yarısı büyüklüğünde', 'Hemen yürüyüp in dışına çıkabilecek kadar gelişmiş', 'Kesede taşınacak kadar gelişmemiş, keseli gibi'], 'Bozayı yavruları inde, kış ortasında yaklaşık yarım kilogram ağırlığında, kör ve neredeyse tüysüz doğar; ilkbahara kadar annenin yağca zengin sütüyle büyür.'),
  ('Kuzey Amerika\'daki kara ayı hakkında hangisi doğrudur?', 'Kahverengi bireyleri de vardır', ['Yalnızca tümüyle siyah bireyleri vardır', 'Bozayıdan belirgin biçimde daha iri yapılıdır', 'Ağırlığı nedeniyle ağaçlara hiç tırmanamaz'], 'Adına karşın kara ayının kahverengi, tarçın rengi ve hatta beyaza yakın bireyleri vardır; bozayıdan küçüktür ve iyi tırmanır.'),
  ('Kokarcanın göze çarpan siyah-beyaz deseni hangi savunma stratejisinin parçasıdır?', 'Uyarıcı renklenme', ['Kamuflaj', 'Batesçi taklitçilik', 'Ölü taklidi'], 'Kokarca gizlenmez; dikkat çekici deseni, avcılara kötü kokulu spreyi hakkında önceden uyarı verir. Buna uyarıcı (aposematik) renklenme denir.'),
  ('Kırmızı panda ile dev panda arasındaki ilişki hakkında hangisi doğrudur?', 'Ayrı familyalardadır', ['Aynı türün iki ayrı renk biçimidir', 'Kırmızı panda, dev pandanın yavru evresidir', 'İkisi de rakungiller familyasında yer alır'], 'Kırmızı panda Ailuridae adlı kendi familyasında yer alır; dev panda ise bir ayıdır. İkisinde de bambu yemek için gelişmiş yalancı başparmak bulunması yakınsak evrimin örneğidir.'),
  ('Sürikatlar beslenirken grubun bir üyesinin yüksek bir noktaya çıkıp çevreyi gözlemesi hangi davranışa örnektir?', 'Nöbetçilik', ['Bölge savunması', 'Kur yapma', 'Göç'], 'Nöbetçi sürikat yırtıcı kuş ya da çakal görünce özel alarm sesleri çıkarır; böylece yere eğilmiş beslenen grup üyeleri zamanında saklanabilir.'),
  ('Benekli sırtlan topluluklarının sosyal yapısında dikkat çeken özellik hangisidir?', 'Dişiler erkeklerden iri ve baskındır', ['Gruplar yalnızca erkeklerden oluşur', 'Yavrular doğar doğmaz gruptan ayrılır', 'En yaşlı erkek bütün kararları verir'], 'Benekli sırtlanlarda dişiler erkeklerden daha iri ve saldırgandır; en düşük sıradaki dişi bile çoğu erkekten üstün konumdadır.'),
  ('Sırtlangiller ailesinden olup neredeyse yalnızca termitle beslenen, dişleri küçülmüş tür hangisidir?', 'Toprak kurdu', ['Kahverengi sırtlan', 'Çizgili sırtlan', 'Afrika yaban köpeği'], 'Toprak kurdu sırtlangillerin üyesidir ama et değil, geceleri uzun yapışkan diliyle topladığı termitlerle beslenir.'),
  ('Bilinen memeli türlerinin yaklaşık yüzde kırkını oluşturan, tür sayısı bakımından en kalabalık memeli takımı hangisidir?', 'Kemirgenler', ['Yarasalar', 'Etçiller', 'Çift toynaklılar'], 'Kemirgenler 2000\'i aşkın türle en kalabalık memeli takımıdır; ikinci sırada yarasalar gelir.'),
  ('Anadolu\'da da yaşayan kör farelerin (Spalax) toprak altında tünel açarken asıl kullandığı araç hangisidir?', 'Kesici dişleri', ['Kürek biçimli ön ayakları', 'Sivri burnu', 'Sert kuyruğu'], 'Kör fareler, kapatılabilen dudaklarının önünde kalan güçlü kesici dişleriyle toprağı kazar; gözleri derinin altında körelmiştir.'),
  ('Kobayların (guinea pig) beslenmesinde dışarıdan C vitamini verilmesi neden gereklidir?', 'İnsanlar gibi bu vitamini kendileri üretemezler', ['C vitamini kürklerinin rengini korur', 'Vücutlarında aşırı C vitamini birikir', 'C vitamini dişlerinin uzamasını durdurur'], 'Memelilerin çoğu C vitaminini kendisi sentezler; insanlar ve kobaylar ise gerekli enzimin geni işlevsiz olduğu için onu besinle almak zorundadır.'),
  ('Kunduzun yassı, pullu kuyruğunu suya sertçe vurmasının işlevi nedir?', 'Yakındaki kunduzları tehlikeye karşı uyarmak', ['Balıkları sersemletip avlamak', 'Yuva duvarını sıkıştırmak', 'Suyu ısıtmak'], 'Tehlike sezen kunduz kuyruğunu suya vurarak yüksek bir şaplama sesi çıkarır ve aile üyelerini uyarır; kuyruk ayrıca yağ deposu ve dümen işlevi görür.'),
  ('Oklukirpilerin dikenlerini düşmanlarına fırlattığı yönündeki yaygın inanç için hangisi doğrudur?', 'Yanlıştır; dikenler ancak temasla takılıp kopar', ['Doğrudur; dikenleri metrelerce uzağa fırlatır', 'Doğrudur; yalnızca yavruları fırlatabilir', 'Yanlıştır; oklukirpilerin dikeni yoktur'], 'Oklukirpi dikenlerini fırlatamaz; kuyruğunu savurarak saldırgana çarpar ve uçlarında geri dönük çengeller bulunan dikenler deriye takılıp kopar.'),
  ('Tavşanların en çok gün doğumu ve gün batımı saatlerinde etkin olmasına ne ad verilir?', 'Alacakaranlık etkinliği', ['Gece etkinliği', 'Gündüz etkinliği', 'Kış dinlenmesi'], 'Alacakaranlıkta etkin (krepüsküler) hayvanlar ışığın az olduğu saatlerde beslenir; bu, hem gündüz hem gece avcılarının etkinliğinin azaldığı bir zaman dilimidir.'),
  ('Bir tavşanın tehlike anında arka ayağıyla yere sertçe vurmasının işlevi nedir?', 'Diğer tavşanları uyarmak', ['Toprağı kazmaya başlamak', 'Avcıyı ısırmaya hazırlanmak', 'Vücudunu ısıtmak'], 'Ayak vurma, yer üzerinden yayılan bir uyarı sinyalidir; yakındaki tavşanlar bu sesle yuvalarına kaçar.'),
  ('Tavşanların gözlerinin başın iki yanında ve yüksekte bulunması ne sağlar?', 'Hemen hemen her yönü aynı anda görebilmek', ['Yakındaki nesneleri büyütmek', 'Gece renkleri seçmek', 'Yalnız önünü net görmek'], 'Tavşanın göz yerleşimi neredeyse tam çevresel görüş sağlar; böylece hem yukarıdan gelen yırtıcı kuşu hem yerdeki avcıyı erken fark edebilir.'),
  ('Kuzey Amerika\'nın sulak alanlarında yaşayan yıldız burunlu köstebeğin burnundaki 22 dokunaçlı yapının işlevi nedir?', 'Avını dokunarak çok hızlı tanımak', ['Suda soluk almak', 'Koku yayarak eş bulmak', 'Toprağı yumuşatmak'], 'Yıldız burnu Eimer organı denen binlerce dokunma alıcısı taşır; hayvan bu sayede avını saniyenin küçük bir kesrinde tanıyıp yutabilir.'),
  ('Avrupa köstebeklerinin yuva odalarında, başlarından ısırılarak hareketsiz bırakılmış canlı solucanlar bulunur. Bu davranışın amacı nedir?', 'Solucanları taze besin olarak depolamak', ['Solucanları yavrulara oyuncak yapmak', 'Toprağı solucanlarla havalandırmak', 'Avcıları solucan kokusuyla uzaklaştırmak'], 'Köstebek solucanların ön ucunu ısırarak onları kaçamaz hâle getirir; canlı kalan solucanlar kış boyunca bozulmayan bir besin deposu olur.'),
  ('Bahçede bir köstebek tümseği görüldüğünde bu yığının oluşma nedeni nedir?', 'Tünel kazılırken çıkan toprağın yüzeye itilmesi', ['Köstebeğin yuvasını yukarıdan havalandırmak için baca açması', 'Solucanların dışkılarıyla toprağı yukarı taşıması', 'Köstebeğin kışlık besin deposunu toprakla örtmesi'], 'Köstebek tünel kazarken kopardığı toprağı dikey bir bacadan yukarı iter; bu toprak yüzeyde tümsek oluşturur.'),
  ('Kirpinin dikenleri yapısal olarak neyin değişmiş biçimidir?', 'Kılların', ['Kemiklerin', 'Tırnakların', 'Pulların'], 'Kirpi dikenleri keratinden yapılmış, içi süngerimsi ve sertleşmiş kıllardır; dökülen dikenlerin yerine yenileri çıkar.'),
  ('Bahçesine gelen bir kirpiyi beslemek isteyen birine neden inek sütü vermemesi önerilir?', 'Kirpiler süt şekerini sindiremez', ['Süt, dikenlerin yumuşayıp dökülmesine yol açar', 'Süt, kış uykusuna yatmalarını engeller', 'Kirpiler hiçbir sıvıyı içemez'], 'Erişkin kirpilerde süt şekerini (laktoz) sindiren enzim yetersizdir; inek sütü ishal ve su kaybına yol açabilir. Su ve uygun kedi maması daha güvenlidir.'),
  ('Sonbaharda bahçede biriken yaprak ve dal yığınlarını yakmadan önce kontrol etmenin kirpiler açısından önemi nedir?', 'Kirpiler bu yığınlarda kış uykusuna yatabilir', ['Kirpiler bu yığınlarda yalnızca yaz aylarında ürer', 'Kirpi dikenleri yanınca zehirli bir gaz açığa çıkar', 'Kirpiler kuru yaprakları yiyerek beslenir'], 'Kirpiler kış uykusu için yaprak ve dal yığınlarının altına yuva yapar; yakılmadan önce yığının kontrol edilmesi kirpilerin ölümünü önler.'),
  ('\'Uçan tilki\' olarak da bilinen büyük meyve yarasalarının çoğu yön bulmada ekolokasyon yerine neye dayanır?', 'Gelişmiş görme ve koku duyularına', ['Yalnızca Dünya\'nın manyetik alanına', 'Yere düşen gölgelerin sıcaklık farklarına', 'Yüzlerindeki uzun dokunma kıllarına'], 'Meyve yarasalarının çoğu iri gözleri ve güçlü koku alma duyularıyla meyve ve çiçek bulur; aralarında yalnızca Rousettus gibi birkaç cins dil tıklatarak basit bir ekolokasyon yapar.'),
  ('\'Yarasalar kördür\' yargısı için hangisi doğrudur?', 'Yanlıştır; bütün yarasalar görebilir', ['Doğrudur; yarasaların gözü yoktur', 'Doğrudur; yalnız ekolokasyonla yön bulurlar', 'Yanlıştır; yarasalar yalnızca kızılötesi görür'], 'Bütün yarasaların gözleri işlevseldir; ekolokasyon yapan türler bile uzun mesafede yön bulmak ve alacakaranlıkta görmek için gözlerini kullanır.'),
  ('Vampir yarasaların kanla beslenmesi hakkında hangisi doğrudur?', 'Akan kanı dilleriyle yalarlar', ['Kanı iğne gibi dişleriyle emerler', 'Avlarını öldürüp kanını içerler', 'Yalnızca insan kanıyla beslenirler'], 'Vampir yarasa keskin kesici dişleriyle deride küçük bir yara açar; tükürüğündeki pıhtılaşmayı önleyen maddeler sayesinde akan kanı yalayarak içer.'),
  ('Kirpiler, sivri fareler ve köstebekler aynı memeli takımında toplanır. Bu takımın ortak beslenme özelliği nedir?', 'Omurgasızlarla beslenmeleri', ['Çoğunlukla ot ve tohumla beslenmeleri', 'Yalnızca meyveyle beslenmeleri', 'Süzerek beslenmeleri'], 'Kirpiler, sivri fareler ve köstebeklerin oluşturduğu böcekçiller (Eulipotyphla) böcek, solucan ve salyangoz gibi küçük omurgasızlarla beslenir.'),
  ('Primatların çoğunun parmak uçlarında pençe yerine bulunan yapı hangisidir?', 'Yassı tırnaklar', ['Çengel biçimli sivri pençeler', 'Toynak benzeri sert kılıflar', 'Yapışkan vantuzlar ve pençeler'], 'Primatların çoğunda parmak uçlarında yassı tırnaklar ve altında dokunmaya çok duyarlı parmak yastıkları bulunur; bu yapı dalları kavramayı kolaylaştırır.'),
  ('Primatlarda gözlerin yüzün önüne doğru yönelmiş olması hangi yeteneği güçlendirir?', 'Derinlik algısı', ['Arkayı görebilme', 'Kızılötesi görme', 'Gece körlüğünden korunma'], 'Öne bakan iki gözün görüş alanları büyük ölçüde örtüşür; beyin bu iki görüntüyü birleştirerek uzaklığı iyi tahmin eder, bu da daldan dala atlarken çok önemlidir.'),
  ('Borneo\'nun mangrov ve nehir kıyısı ormanlarında yaşayan, erkeklerinin çok büyük ve sarkık bir burnu olan maymun hangisidir?', 'Hortumlu maymun', ['Uluyan maymun', 'Örümcek maymunu', 'Gelada'], 'Hortumlu maymun erkeklerinin büyük burnunun seslerini güçlendirdiği ve dişilerin tercihinde rol oynadığı düşünülür; bu maymunlar iyi yüzücüdür.'),
  ('İnsan dışındaki primatlar arasında en kuzeyde yaşayan ve kışın bazı gruplarının sıcak su kaynaklarında ısındığı bilinen tür hangisidir?', 'Japon makakı', ['Berberi makakı', 'Altın kalkık burunlu maymun', 'Rhesus makakı'], 'Japon makakları karlı dağlarda yaşar; Nagano\'daki bir grubun kışın kaplıcalara girmesi ünlüdür.'),
  ('Goril ve şempanzelerin yerde dört ayak üstünde ilerlerken ön ellerini kullanma biçimine ne ad verilir?', 'Parmak eklemleri üzerinde yürüme', ['Avuç içi üzerine basarak yürüme', 'Bilekleri üzerinde sürünerek ilerleme', 'Yumruk sıkıp iki ayakla sıçrama'], 'Goril ve şempanzeler ön ellerini yumruk gibi kıvırıp parmakların orta eklemleri üzerine basarak yürür; orangutanlar ise genellikle yumruk ya da avuç kenarına basar.'),
  ('Yaşayan türler arasında insanın en yakın akrabası olarak kabul edilen hayvanlar hangileridir?', 'Şempanze ve bonobo', ['Goril ve orangutan', 'Jibon ve siyamang', 'Babun ve mandril'], 'Genetik çalışmalar insan soyunun yaklaşık 6–7 milyon yıl önce şempanze ve bonobonun ortak atasından ayrıldığını gösterir; goriller biraz daha uzak, orangutanlar daha da uzaktır.'),
  ('Bonoboların şempanzelerden ayrı bir tür olarak evrimleşmesinde hangi coğrafi engelin rol oynadığı düşünülür?', 'Kongo Nehri', ['Sahra Çölü', 'Büyük Rift Vadisi gölleri', 'Kilimanjaro Dağı'], 'Bonobolar Kongo Nehri\'nin güneyinde, şempanzeler kuzeyinde yaşar; büyük insansılar iyi yüzemediği için nehir iki toplulukların ayrışmasını sağlamıştır.'),
  ('Orangutanlar ve diğer büyük insansılar her akşam nasıl bir hazırlık yapar?', 'Yeni bir uyku yuvası yapar', ['Yerde derin bir çukur kazıp içine girer', 'Grupça en yakın mağaraya çekilir', 'Bir dala kuyruğuyla sıkıca bağlanır'], 'Büyük insansılar çoğunlukla her gece dalları bükerek ve yapraklarla döşeyerek yeni bir yuva hazırlar; bu, onları yerdeki avcılardan ve rahatsızlıklardan korur.'),
  ('Kıl köklerine açılan ve kılları ile deriyi yağlayarak suya karşı koruyan bezler hangileridir?', 'Yağ bezleri', ['Ter bezleri', 'Meme bezleri', 'Tükürük bezleri'], 'Yağ bezleri salgıladıkları yağlı maddeyle kılları kayganlaştırır, derinin kurumasını önler ve kürke bir miktar su geçirmezlik kazandırır.'),
  ('Albino bir tavşanın gözlerinin kırmızımsı pembe görünmesinin nedeni nedir?', 'Kan damarlarının görünmesi', ['Gözlerinin sürekli iltihaplı ve kanlı olması', 'Kırmızı bir pigmentin aşırı üretilmesi', 'Gözlerine ışığın hiç girememesi'], 'Albinizmde melanin üretilemez; renksiz iristen içerideki kan damarları görünür ve göz pembe-kırmızı görünür.'),
  ('Sığır, koyun ve keçi gibi geviş getirenlerin üst çenesinin ön kısmında kesici diş yerine ne bulunur?', 'Sert bir diş eti yastığı', ['Fildişi gibi uzun dişler', 'Kemik bir gaga', 'Keratin bir boynuz plakası'], 'Geviş getirenlerde üst kesici dişler yoktur; otlar alt kesici dişlerle üstteki sert yastık arasında sıkıştırılıp dil yardımıyla koparılır.'),
  ('Domuzun diş formülü her çene yarısında 3 kesici, 1 köpek, 4 küçük azı ve 3 azıdır. Bu formül plasentalı memelilerin atasal tam diş takımıyla aynıdır. Domuzun toplam diş sayısı kaçtır?', '44', ['40', '42', '48'], 'Bir çene yarısında 3+1+4+3=11 diş vardır; dört çene yarısı için 11×4=44 eder.'),
  ('Ev faresi ve sıçanlarda her çene yarısında yalnızca 1 kesici ve 3 azı dişi bulunur. Bu hayvanların toplam diş sayısı kaçtır?', '16', ['12', '20', '22'], 'Her çene yarısında 1+3=4 diş vardır; dört yarı için 4×4=16 diş eder. Köpek dişi ve küçük azı yoktur.'),
  ('Kemirgenler, tavşanlar ve fillerde kesici dişlerin kökleri açık kalır. Bu özelliğin sonucu nedir?', 'Dişlerin ömür boyu uzaması', ['Dişlerin hiç aşınmaması', 'Dişlerin yılda bir dökülmesi', 'Dişlerin içinin boşalması'], 'Kökü açık kalan dişlerde diş yapan dokular çalışmayı sürdürür; bu nedenle kemirgen kesicileri ve fil fildişleri hayvan yaşadıkça büyür.'),
  ('İnsanda erişkinlikte üst ve alt çenelerin her yarısında kaç küçük azı dişi bulunur?', 'İki', ['Bir', 'Üç', 'Dört'], 'İnsanın kalıcı diş formülü her çene yarısında 2 kesici, 1 köpek, 2 küçük azı ve 3 azıdır; plasentalıların atasal formülündeki dört küçük azıdan ikisi kaybolmuştur.'),
  ('Geviş getiren bir sığırda kendi sindirim enzimlerini salgılayan ve tek midelilerin midesine karşılık gelen bölme hangisidir?', 'Şirden', ['İşkembe', 'Börkenek', 'Kırkbayır'], 'İşkembe, börkenek ve kırkbayır mikropların çalıştığı ön bölmelerdir; şirden ise asit ve enzim salgılayan \'gerçek mide\'dir.'),
  ('Dev panda neredeyse yalnızca bambu yediği hâlde sindirim sistemi bir etçilinkine benzer. Bunun sonucu nedir?', 'Günün büyük kısmını yiyerek geçirir', ['Bambuyu tamamen sindirdiği için çok az yer', 'Bambuyu midesinde aylarca saklayıp kışın kullanır', 'Bambuyu geviş getirerek iki kez çiğner'], 'Kısa ve basit bağırsağı nedeniyle dev panda bambunun ancak küçük bir bölümünden yararlanır; bunu telafi etmek için günde 10 saati aşkın süre yemek yer.'),
  ('Etçil ve otçul memelilerin bağırsak uzunlukları karşılaştırıldığında genel olarak hangisi doğrudur?', 'Otçullarınki oransal olarak daha uzundur', ['Etçillerin bağırsağı her zaman çok daha uzundur', 'İkisinin bağırsağı vücuda oranla eşit uzunluktadır', 'Otçulların ince bağırsağı hiç bulunmaz'], 'Bitki hücre duvarının sindirimi yavaş ve zordur; bu nedenle otçullarda besinin uzun süre kalabildiği uzun bağırsaklar ve büyük mayalanma odaları gelişmiştir.'),
  ('Dalan memelilerde su altına girildiğinde kalp atışının belirgin biçimde yavaşlaması ve kanın daha çok beyin ile kalbe yönlendirilmesine ne ad verilir?', 'Dalma refleksi', ['Kış uykusu', 'Günlük torpor', 'Yaz uykusu'], 'Dalma refleksinde kalp atışı yavaşlar (bradikardi) ve kol-bacak gibi çevre dokulara giden kan azaltılır; böylece sınırlı oksijen en hayati organlara ayrılır. İnsanlarda da zayıf bir biçimi görülür.'),
  ('Yeni doğan memelilerde ve kış uykusundan uyanan hayvanlarda titremeden ısı üretilmesini sağlayan doku hangisidir?', 'Kahverengi yağ dokusu', ['Deri altı beyaz yağ dokusu', 'Eklemlerdeki kıkırdak doku', 'Uzun kemiklerdeki kemik iliği'], 'Kahverengi yağ hücreleri bol mitokondri içerir ve bu mitokondriler enerjiyi ATP yerine doğrudan ısı olarak açığa çıkarır; bu da titremeden ısınmayı sağlar.'),
  ('Kanguruların sıcak günlerde ön kollarının iç yüzünü yalaması nasıl bir yarar sağlar?', 'Tükürüğün buharlaşması kanı soğutur', ['Kollarındaki eski kılları dökmeye yardım eder', 'Kesedeki yavruya tükürükle besin sağlar', 'Kollarının derisine tuz depolar'], 'Kanguruların ön kollarının iç yüzünde deriye çok yakın kan damarları vardır; yalanan yüzeyde tükürük buharlaştıkça bu damarlardaki kan soğur.'),
  ('Köpeklerin ve memelilerin çoğunun renk görmesi insanınkinden nasıl farklıdır?', 'Daha az renk ayırt ederler', ['Hiç renk görmezler, yalnız siyah-beyaz görürler', 'Dört tip koniyle insandan çok daha fazla renk görürler', 'Yalnızca kırmızıyı görürler'], 'Memelilerin çoğu iki renkli (dikromat) görür; kırmızı ile yeşili ayırt etmekte zorlanırlar. Üç tip koni taşıyan üç renkli görüş Eski Dünya primatlarında ve insanda gelişmiştir.'),
  ('Kedilerin insanın duyamayacağı yüksek frekanslı sesleri işitebilmesi onlara avlanmada nasıl bir yarar sağlar?', 'Farelerin tiz seslerini duymak', ['Yarasaları ekolokasyonla bulmak', 'Uzaktaki filleri duymak', 'Yağmuru önceden sezmek'], 'Kedilerin işitme sınırı insanınkinin çok üstüne çıkar; bu sayede farelerin birbirine gönderdiği yüksek frekanslı sesleri ve hışırtıları duyarlar.'),
  ('Kedilerin dikey yarık biçimli göz bebekleri ile ilgili hangisi doğrudur?', 'Işığı geniş aralıkta ayarlar', ['Gece karanlığında hiç açılmaz', 'Yalnızca kırmızı dalga boyundaki ışığı geçirir', 'Başın arkasını da görmeye yarar'], 'Yarık göz bebeği çok dar bir çizgiye kadar kapanıp gece de tamamen açılabilir; bu, gece ve gündüz avlanan pusu avcıları için ışığı hassas biçimde ayarlamayı sağlar.'),
  ('Gece etkin memelilerin retinasında hangi tip ışık alıcı hücreler daha bol bulunur?', 'Çubuk hücreler', ['Koni hücreler', 'Pigment hücreleri', 'Kas hücreleri'], 'Çubuk hücreler loş ışığa çok duyarlıdır ama renk ayırt etmez; gece etkin memelilerin retinası bu hücreler bakımından zengindir.'),
  ('Kurbağa, kertenkele ve kuşlarla karşılaştırıldığında memelilerin kulak yapısını ayıran dışa doğru belirgin özellik hangisidir?', 'Dış kulak kepçesi', ['Kulak zarı', 'İç kulak', 'Denge organı'], 'Kulak zarı ve iç kulak diğer karasal omurgalılarda da vardır; sesi toplayıp yönlendiren dış kulak kepçesi ise memelilere özgüdür, ancak bazı sucul ve toprak altı memelilerinde kaybolmuştur.'),
  ('Kedi, tavşan ve develerde yumurtlamanın kendiliğinden belirli bir döngüyle değil de çiftleşmenin uyarısıyla gerçekleşmesine ne ad verilir?', 'Uyarılmış yumurtlama', ['Kendiliğinden yumurtlama', 'Gecikmeli tutunma', 'Partenogenez'], 'Uyarılmış yumurtlamada çiftleşme sırasındaki uyarı hormon salgısını tetikler ve yumurtlama ardından gerçekleşir; bu, eşlerin seyrek karşılaştığı türlerde döllenme olasılığını artırır.'),
  ('Aşağıdaki memeliler gebelik süreleri kısadan uzuna doğru sıralandığında hangi sıralama doğrudur?', 'Fare, kedi, inek, at', ['Kedi, fare, at, inek', 'Fare, inek, kedi, at', 'At, inek, kedi, fare'], 'Fare yaklaşık 3 hafta, kedi yaklaşık 2 ay, inek yaklaşık 9 ay, at yaklaşık 11 ay gebe kalır; genel olarak iri hayvanların gebeliği daha uzundur.'),
  ('At ve zürafa yavrularının doğduktan kısa süre sonra ayağa kalkıp annesini izleyebilmesi gibi, gelişmiş doğan yavrular için hangi terim kullanılır?', 'Prekosyal (erken gelişmiş)', ['Altrisyal (bakıma muhtaç)', 'Keseli', 'Larva'], 'Prekosyal yavrular gözleri açık, kürklü ve hareket edebilir hâlde doğar; açık alanda yaşayan av hayvanlarında bu özellik yaygındır. Altrisyal yavrular ise çıplak ve çaresiz doğar.'),
  ('Anne kedi yavrusunu ensesinden ağzıyla kavradığında yavrunun bedeninin gevşeyip hareketsiz kalmasının yararı nedir?', 'Güvenle taşınabilmesi', ['Yavrunun hemen uykuya geçip büyümesi', 'Annenin yavrunun ağırlığını ölçebilmesi', 'Yavrunun emmeye hazırlanması'], 'Ense derisinden tutulan yavru refleks olarak gevşer ve bacaklarını toplar; böylece anne onu yuvalar arasında güvenle taşır.'),
  ('Doğumdan sonraki ilk saatlerde koyunların kendi kuzusunu koklayarak tanıyıp başka kuzuların emmesine izin vermemesi neyi gösterir?', 'Kokuya dayalı hızlı bir bağ kurulduğunu', ['Koyunların yavrularını gözle hiç göremediğini', 'Kuzuların doğuştan sütle beslenmediğini', 'Sürüdeki bütün kuzuların ortak bakıldığını'], 'Doğumdan hemen sonraki kısa bir duyarlı dönemde koyun kuzusunun kokusunu öğrenir; sonrasında yalnızca bu kokudaki kuzuyu emzirir.'),
  ('Fil ve aslan gibi birçok memelide dişiler doğdukları grupta kalırken genç erkekler gruptan ayrılır. Bu düzenin en önemli yararı nedir?', 'Yakın akraba çiftleşmesini azaltmak', ['Grubun avlanma başarısını sıfırlamak', 'Dişilerin daha hızlı büyümesini sağlamak', 'Erkeklerin kış uykusuna yatabilmesi'], 'Bir eşeyin doğduğu gruptan ayrılması, kardeşler ve yakın akrabalar arasında çiftleşme olasılığını düşürür; böylece akraba evliliğinin zararlı etkileri azalır.'),
  ('Çitanın çok hızlı koşabilmesine katkı sağlayan iskelet özelliği hangisidir?', 'Esnek omurgası', ['Dört ayağındaki sert toynakları', 'Kuşlarınki gibi içi boş kemikleri', 'Arka bacaklarına göre çok kısa ön bacakları'], 'Çitanın omurgası koşarken yay gibi bükülüp açılır; bu hareket adım uzunluğunu ciddi ölçüde artırır ve bacaklara ek itme sağlar.'),
  ('Yavaşlıklarıyla bilinen tembel hayvanların suda nasıl hareket ettiği bilinir?', 'İyi yüzerler', ['Suya hiç giremezler, hemen batarlar', 'Yalnızca su altında dipte yürürler', 'Sudayken kış uykusuna yatarlar'], 'Tembel hayvanlar kulaç atar gibi uzun ön kollarını kullanarak iyi yüzer; nehirleri geçerken ya da su basan ormanda dolaşırken bu yeteneklerini kullanırlar.'),
  ('Yaklaşık üç milyon yıl önce Panama Kıstağı\'nın oluşmasından sonra iki Amerika kıtası arasında memeli göçü başlamıştır. Bu olaya ne ad verilir?', 'Büyük Amerika Değişimi', ['Kıtasal Kayma Göçü', 'Büyük Bering Göçü', 'Gondvana Ayrılması'], 'Kara köprüsüyle armadillo, opossum ve oklukirpi gibi türler kuzeye; kedigiller, köpekgiller, geyikler ve ayılar gibi türler güneye geçmiştir.'),
  ('Adalarda küçük memelilerin, örneğin bazı sıçanların, anakaradaki akrabalarından çok daha iri hâle gelmesi hangi kavramla açıklanır?', 'Ada devleşmesi', ['Ada cüceleşmesi', 'Bergmann kuralı', 'Yakınsak evrim'], 'Avcının az olduğu ve rekabetin farklılaştığı adalarda küçük memeliler büyüme eğilimi gösterebilir; büyük memeliler ise çoğunlukla küçülür. Bu iki eğilime birlikte \'ada kuralı\' denir.'),
  ('Türkiye\'de doğal olarak yaşayan tek ayı türü hangisidir?', 'Bozayı', ['Asya kara ayısı', 'Güneş ayısı', 'Tembel ayı'], 'Türkiye\'de yalnızca bozayı (Ursus arctos) yaşar; Karadeniz ormanları ile Doğu ve Güneydoğu Anadolu\'nun dağlık kesimlerinde dağılış gösterir.'),
  ('Ankara keçisinden elde edilen, parlak ve ipeksi lifine ne ad verilir?', 'Tiftik', ['Kaşmir', 'Angora yünü', 'Yapağı'], 'Ankara keçisinin uzun, parlak ve kıvrımlı lifine tiftik (moher) denir. Angora yünü ise Ankara tavşanından elde edilir; kaşmir başka keçi ırklarının ince alt yünüdür.'),
  ('Van kedisinin en tanınmış davranışsal özelliği hangisidir?', 'Suda yüzmeyi sevmesi', ['Hiç miyavlamaması', 'Kış uykusuna yatması', 'Yalnız gece beslenmesi'], 'Van kedisi Van Gölü çevresine özgü, uzun tüylü bir ırktır; çoğu kedinin aksine suya girmekten çekinmemesi ve sıklıkla iki farklı göz rengine sahip olmasıyla tanınır.'),
  ('Sivas yöresine özgü olan ve sürüleri kurtlara karşı korumak için yetiştirilen iri çoban köpeği ırkı hangisidir?', 'Kangal', ['Türk tazısı', 'Zağar', 'Akbaş'], 'Kangal köpeği iri yapısı, siyah yüz maskesi ve sürü koruma yeteneğiyle bilinen Anadolu ırkıdır. Akbaş da bir çoban köpeğidir ama beyaz renkli ve farklı bir ırktır.'),
  ('Akkaraman gibi bazı yerli koyun ırklarının kuyruklarında büyük bir yağ birikimi bulunur. Bu özelliğin bozkır koşullarına uyumu nedir?', 'Kıt dönemler için enerji deposu olması', ['Kuyruğu sinekleri kovmak için ağırlaştırması', 'Koyunun derin sularda yüzmesini kolaylaştırması', 'Kurtları keskin kokusuyla uzaklaştırması'], 'Yağlı kuyruk, deve hörgücü gibi bir yedek enerji kaynağıdır; kışın ve kurak dönemde otun azaldığı bozkırlarda koyunun dayanıklılığını artırır.'),
  ('Afyon kaymağının geleneksel olarak sütünden yapıldığı evcil hayvan hangisidir?', 'Manda', ['Keçi', 'Koyun', 'Tek hörgüçlü deve'], 'Afyon kaymağı yağ oranı yüksek manda sütünden yapılır; manda sütü inek sütünden belirgin biçimde daha yağlıdır.'),
  ('Evcil domuzun yabani atası hangi türdür?', 'Yaban domuzu', ['Pekari', 'Babirusa', 'Siğilli domuz'], 'Evcil domuz, Anadolu ve Doğu Asya dahil birkaç merkezde yaban domuzundan bağımsız olarak evcilleştirilmiştir; Diyarbakır\'daki Çayönü bu sürecin erken izlerini taşıyan yerleşimlerdendir.'),
  ('Ankara tavşanından elde edilen lifin, koyun yününe göre bilinen bir üstünlüğü hangisidir?', 'Daha hafif ve sıcak olması', ['Hiç ısı tutmayıp serin olması', 'Suya tamamen geçirimsiz olması', 'Ateşe karşı yanmaz olması'], 'Angora yünü liflerinin içi kısmen boştur; bu nedenle çok hafiftir ve aynı ağırlıktaki koyun yününden daha fazla ısı tutar.'),
  ('Buzul çağında Güney Amerika\'da yaşamış, fil boyutuna ulaşan ve arka ayakları üzerinde doğrulup ağaçlardan beslenebilen dev memeli hangisidir?', 'Megatherium', ['Mastodon', 'Paraceratherium', 'Toxodon'], 'Megatherium dev bir yer tembel hayvanıdır; bugünkü ağaç tembel hayvanlarının uzak akrabasıdır ve yerde yaşardı.'),
  ('Genetik çalışmalara göre yünlü mamutun yaşayan en yakın akrabası hangisidir?', 'Asya fili', ['Afrika savan fili', 'Afrika orman fili', 'Deniz ineği'], 'DNA çalışmaları yünlü mamutun Afrika fillerinden çok Asya filine yakın olduğunu göstermiştir.'),
  ('Basilosaurus fosillerinde gövdeye göre çok küçük, işlevi sınırlı arka bacaklar bulunması balina evrimi hakkında neyi destekler?', 'Kara memelilerinden türediklerini', ['Balinaların kemikli balıklardan türediğini', 'Balinaların bacaklarının yeniden uzayacağını', 'Balinaların aslında sürüngen olduğunu'], 'Körelmiş arka bacaklar, balinaların atalarının karada yürüyen memeliler olduğunu gösteren önemli kanıtlardandır; bazı yaşayan balinalarda da gövde içinde küçük kalça kemikleri bulunur.'),
  ('Bazı yunus ve balina embriyolarında gelişimin erken evresinde arka bacak tomurcukları belirip sonra kaybolur. Bu gözlem en iyi nasıl yorumlanır?', 'Atalarında arka bacak bulunduğunun izi', ['Embriyonun kusurlu geliştiğinin kanıtı', 'Erişkinde bacakların yeniden çıkacağının işareti', 'Yunusların balık olduğunun kanıtı'], 'Embriyodaki geçici yapılar, soyun evrimsel geçmişini yansıtabilir; arka bacak tomurcukları balinaların dört bacaklı atalarından gelen bir kalıntıdır.'),
  ('Yünlü mamut ve yünlü gergedan gibi buzul çağı memelilerinin kürkü, deri ve iç organlarıyla bugüne ulaşabilmesinin başlıca nedeni hangisidir?', 'Kalıcı donmuş toprakta kalmaları', ['Sıcak volkan külünün altına gömülmeleri', 'Ağaç reçinesi (kehribar) içinde kalmaları', 'Tuz gölleri tabanında kurumaları'], 'Sibirya ve Alaska\'daki kalıcı donmuş toprak, ölen hayvanları derin dondurucu gibi saklar; bu sayede yumuşak dokular, kürk ve hatta mide içerikleri incelenebilmiştir.'),
  ('Sibirya\'da donmuş toprakta bulunan mamut leşlerinin mide içerikleri incelendiğinde bu hayvanların büyük ölçüde neyle beslendiği anlaşılmıştır?', 'Otlar ve sazlar', ['Balıklar', 'Başka memelilerin eti', 'Yalnız çam kozalakları'], 'Mide ve bağırsak içerikleri, yünlü mamutların buzul çağının soğuk bozkırlarında yetişen otlar, sazlar ve otsu bitkilerle beslendiğini gösterir.'),
  ('Tek toynaklılar takımında bugün yaşayan üç familya hangileridir?', 'Atgiller, gergedanlar ve tapirler', ['Atgiller, domuzlar ve develer', 'Gergedanlar, filler ve su aygırları', 'Tapirler, zürafalar ve okapiler'], 'Tek toynaklılar (Perissodactyla) ağırlığı ortadaki parmağın taşıdığı at, gergedan ve tapirleri içerir; domuz, deve ve su aygırı çift toynaklıdır.'),
  ('Yaşayan kedi türlerinin en irisi hangisidir?', 'Kaplan', ['Afrika aslanı', 'Jaguar', 'Puma'], 'Kaplan, özellikle Sibirya (Amur) kaplanı, yaşayan en büyük kedi türüdür; aslan ikinci sırada gelir.'),
  ('Yaşayan en büyük antilop türü olan ve Afrika savanlarında yaşayan sarmal boynuzlu hayvan hangisidir?', 'Eland', ['Gnu', 'Impala', 'Kudu'], 'Eland, erkekleri bir tonu bulabilen en iri antiloptur; iki eşeyde de sarmal boynuzlar bulunur.'),
  ('Hayvanlar âleminde bilinen en büyük beyne sahip tür hangisidir?', 'İspermeçet balinası', ['Afrika savan fili', 'Mavi balina', 'Orka'], 'İspermeçet balinasının beyni yaklaşık 8 kg ağırlığıyla bilinen en büyük beyindir; karada en büyük beyin ise filindir.'),
  ('Genç memelilerin kovalamaca, boğuşma ve sıçrama gibi oyunlarının işlevine ilişkin en çok desteklenen açıklama hangisidir?', 'Becerileri güvenle denemek', ['Fazla yağı hızla yakmak', 'Annelerinden uzaklaşmak', 'Kış uykusuna hazırlanmak'], 'Oyun, yavruların ileride gerekecek hareket ve sosyal becerileri gerçek bir tehlike olmadan denemesini sağlar; kurallara uyan oyunlar grup içi ilişkileri de güçlendirir.'),
  ('Kar tavşanı ve kakım gibi hayvanlarda sonbaharda beyaz kış kürkünün çıkmaya başlamasını asıl tetikleyen çevresel etken hangisidir?', 'Gün uzunluğunun kısalması', ['İlk karın yağması', 'Hava sıcaklığının sıfırın altına düşmesi', 'Besinin azalması'], 'Tüy değişimi büyük ölçüde gün uzunluğuna bağlı hormonal bir saatle düzenlenir; bu yüzden kar geç yağdığında beyaz hayvan kahverengi zeminde göze batabilir.'),
  ('Bozayıların sonbaharda günde on binlerce kalori alacak kadar aşırı yemek yediği döneme ne ad verilir?', 'Hiperfaji', ['Estivasyon', 'Kızgınlık', 'Gecikmeli tutunma'], 'Hiperfaji döneminde ayılar meyve, fındık ve somon gibi besinlerle hızla yağ depolar; bu yağ kış dinlenmesi boyunca tek enerji kaynakları olur.'),
  ('Kızıl sincapların sonbaharda topladıkları mantarları dallara asıp bekletmesinin amacı nedir?', 'Mantarları kurutup kış için saklamak', ['Mantarlarla avcıları zehirlemek', 'Mantarların spor yaymasına yardım etmek', 'Yuvasını süslemek'], 'Kızıl sincaplar mantarları ağaç dallarına sıkıştırarak kurutur; kurumuş mantar çürümeden saklanabilir ve kışın besin kaynağı olur.'),
  ('Geyiklerin kış kürkünü oluşturan kılların içinin havayla dolu olmasının işlevi nedir?', 'Isı yalıtımını artırmak', ['Suda batmayı kolaylaştırmak', 'Kürkü ağırlaştırmak', 'Ses çıkarmak'], 'İçi boş kıllar hava hapseder; hava iyi bir yalıtkan olduğu için kalın kış kürkü vücut ısısının kaybını büyük ölçüde azaltır.'),
  ('Çitaların öldürdüğü avın bir bölümünü aslan ve sırtlanların zorla elinden alması hangi kavramla adlandırılır?', 'Kleptoparazitlik', ['Yırtıcılık', 'Kommensalizm', 'Mutualizm'], 'Kleptoparazitlik, bir hayvanın başka bir hayvanın elde ettiği besini çalması ya da gasp etmesidir; daha hafif yapılı çitalar avlarını sık sık bu yolla kaybeder.'),
  ('Serengeti\'de yaban öküzü (gnu) dişilerinin büyük çoğunluğunun birkaç haftalık kısa bir dönemde doğurmasının yavrular için yararı nedir?', 'Avcıların doyup yetişememesi', ['Yavruların birbirini emzirebilmesi', 'Doğumun yalnızca yağmurlu gecelere denk gelmesi', 'Avcıların bu dönemde kış uykusunda olması'], 'Eş zamanlı doğumda avcılar kısa sürede bol yavruyla karşılaşır ve hepsini tüketemez; bu \'avcıyı doyurma\' etkisi tek bir yavrunun hayatta kalma olasılığını artırır.'),
  ('Zürafa, gnu ve zebra gibi otçulların yavrularının doğumdan sonra çok kısa sürede ayağa kalkıp koşabilmesinin başlıca nedeni nedir?', 'Avcılardan kaçma zorunluluğu', ['Annelerinin onları emzirmemesi', 'Kış uykusuna hazırlanmaları', 'Yuvalarının ağaçta olması'], 'Saklanacak yer bulunmayan açık alanlarda doğan yavruların sürüyle birlikte hareket edebilmesi hayatta kalmaları için gereklidir.'),
  ('Aslanlar avlanırken bazı dişilerin avı belli bir yöne sürmesi, diğerlerinin ise o yönde pusuya yatması hangi avlanma özelliğini gösterir?', 'Görev paylaşımı', ['Kleptoparazitlik', 'Bölge savunması', 'Eşeysel seçilim'], 'Bazı aslan gruplarında dişilerin \'kanat\' ve \'merkez\' gibi tutarlı roller üstlendiği gözlenmiştir; bu görev paylaşımı av başarısını artırır.'),
  ('Kutuplarda ve dağlarda yaşayan memelilerin kışın beyaz, yazın koyu renk olmasının dışında yıl boyu beyaz kalan bir memeli örneği hangisidir?', 'Kutup ayısı', ['Kar tavşanı', 'Kakım', 'Kutup tilkisi'], 'Kar tavşanı, kakım ve kutup tilkisinin çoğu popülasyonu mevsime göre renk değiştirir; kutup ayısı ise yıl boyunca beyaz görünür.'),
  ('Kutup ayılarında kış boyunca karda kazılmış bir ine giren bireyler genellikle hangileridir?', 'Gebe dişiler', ['Bütün erkekler', 'Yalnızca yavrular', 'Yaşlı erkekler'], 'Kutup ayılarında yalnızca gebe dişiler kışı karda kazdıkları bir inde geçirir; yavrular burada doğar. Diğer bireyler kış boyunca buz üzerinde etkin kalabilir.'),
  ('Büyük kediler arasında doğal yayılış alanı en geniş olan, Afrika\'nın büyük bölümünden Güneydoğu Asya\'ya kadar uzanan tür hangisidir?', 'Leopar', ['Bengal kaplanı', 'Afrika aslanı', 'Çita'], 'Leopar yağmur ormanından çöl kenarlarına, dağlardan kent çevrelerine kadar çok farklı ortamlara uyum sağlayabilen, en geniş yayılışlı büyük kedidir.'),
  ('Sahra ve Arabistan çöllerinde yaşayan kum kedisinin ayak tabanlarının yoğun kıllarla kaplı olmasının yararı nedir?', 'Kumda yanmamak ve batmamak', ['Ağaçlara tırmanmak', 'Suyun üstünde yürümek', 'Avına zehir bulaştırmak'], 'Kıllı tabanlar sıcak kuma karşı yalıtım sağlar, ağırlığı yayarak gevşek kumda yürümeyi kolaylaştırır ve ayak izlerini belirsizleştirir.'),
  ('Kuzey Amerika\'da yaşayan gri tilkiyi diğer tilkilerin çoğundan ayıran yetenek hangisidir?', 'Ağaçlara tırmanabilmesi', ['Kışı uykuda geçirmesi', 'Büyük sürüler hâlinde avlanması', 'Yalnızca balıkla beslenmesi'], 'Gri tilki kıvrılabilen pençeleri ve dönebilen ön ayaklarıyla ağaç gövdelerine tırmanabilir; köpekgiller arasında bu yetenek oldukça nadirdir.'),
  ('Erkek gorillerin ayağa kalkıp avuçlarıyla göğüslerine vurmasının başlıca işlevi nedir?', 'Güç gösterisi ve iletişim', ['Sindirime yardım etmek', 'Akciğerlerindeki mukusu temizlemek', 'Yavrularını uyutmak'], 'Göğüs vurma sesi ormanda uzağa yayılır; araştırmalar sesin frekansının erkeğin vücut büyüklüğü hakkında bilgi taşıdığını, böylece rakiplere ve dişilere sinyal verdiğini göstermiştir.'),
  ('Yaşayan en büyük keseli hangisidir?', 'Kırmızı kanguru', ['Koala', 'Tazmanya canavarı', 'Vombat'], 'Kırmızı kanguru erkeklerinin boyu ayakta 1,5 metreyi geçebilir; yaşayan en iri keseli hayvandır.'),
  ('Kutup ayılarının uzun mesafe yüzebilmesine katkı sağlayan özelliklerden biri hangisidir?', 'Kürek gibi geniş ön patileri', ['Perdeli arka ayakları ve kuyruğu', 'Solungaçlara benzer burun kıvrımları', 'İçi boş kemikleri'], 'Kutup ayısı geniş ön patilerini kürek gibi kullanarak yüzer; kalın yağ tabakası da hem yalıtım hem kaldırma kuvveti sağlar. Bu nedenle bilimsel adı \'deniz ayısı\' anlamına gelir.'),
  ('Güneydoğu Asya\'nın sulak alanlarında yaşayan balıkçı kedinin avlanma alışkanlığı hangisidir?', 'Suya girip balık yakalamak', ['Ağaç tepesinde kuş yuvası aramak', 'Yalnızca leşle beslenmek', 'Termit yuvalarını kazmak'], 'Balıkçı kedi kısmen perdeli ön ayakları ve yağlı kürkü sayesinde suya girmekten çekinmez; balıkları patisiyle sudan çıkarır ya da dalarak yakalar.'),
  ('Beynin dış yüzeyini oluşturan ve algı, öğrenme ve karar verme gibi işlevlerde rol oynayan altı katmanlı neokorteks hangi omurgalı grubuna özgüdür?', 'Memeliler', ['Kuşlar', 'Sürüngenler', 'Kemikli balıklar'], 'Altı katmanlı neokorteks memelilerin ayırt edici beyin yapısıdır; kuşlarda benzer işlevleri farklı düzenlenmiş beyin bölgeleri üstlenir.'),
  ('Doğu Afrika\'da yaşayan ve arka bacakları üzerinde dimdik dikilip uzun boynuyla yüksek dallardaki yaprakları yiyebilen antilop hangisidir?', 'Gerenuk', ['Gnu', 'Eland', 'Springbok'], 'Gerenuk ince uzun boynu ve arka bacaklar üzerinde uzun süre dengede durabilmesiyle diğer antiloplara erişilemeyen yaprakları yer; suyunu da büyük ölçüde besininden alır.'),
  ('İtalya\'da Alp dağ keçilerinin neredeyse dik bir baraj duvarına tırmandığı gözlenmiştir. Bu davranışın nedeni nedir?', 'Taştaki tuzu yalamak', ['Kurtlardan saklanmak için yuva yapmak', 'Suya atlayıp serinlemek', 'Duvardaki yosunlarla beslenmek'], 'Otçullar bitkilerden yeterli sodyum alamaz; dağ keçileri tuz kristallerine ulaşmak için baraj duvarı gibi tehlikeli yüzeylere bile tırmanır.'),
  ('Orta Çağ\'da Avrupa\'da milyonlarca kişiyi öldüren veba salgınında bakteriyi taşıyan pirelerin başlıca konağı olarak kabul edilen kemirgen hangisidir?', 'Kara sıçan', ['Kunduz', 'Kapibara', 'Gri ağaç sincabı'], 'Veba bakterisi (Yersinia pestis) kara sıçan gibi kemirgenlerin pirelerince taşınır; pireler sıçanlar ölünce insanlara geçerek salgını yayar.'),
  ('Arjantin bozkırlarında yaşayan ve tavşana benzediği için \'Patagonya tavşanı\' da denen mara aslında hangi gruba aittir?', 'Kemirgenler', ['Tavşanımsılar', 'Keseliler', 'Çift toynaklılar'], 'Mara, kobay ve kapibaranın akrabası olan iri bir kemirgendir; uzun bacakları ve tavşanı andıran görünüşüyle açık bozkırda koşmaya uyum sağlamıştır.'),
  ('Ev kedilerinin mırlama sesi nasıl üretilir?', 'Gırtlak kaslarının titreşimiyle', ['Burundaki hava keselerinin titremesiyle', 'Diş gıcırdatmayla', 'Karın kaslarının vurmasıyla'], 'Mırlamada gırtlak kasları saniyede onlarca kez kasılıp gevşeyerek ses tellerini titreştirir; ses hem nefes alırken hem verirken üretilir.'),
  ('Kurtlar nadiren havlarken evcil köpeklerin çok sık havlaması en çok neyle açıklanır?', 'Evcilleşme ve insan seçilimi', ['Köpeklerin ses tellerinin daha uzun olması', 'Kurtların hiç ses çıkaramaması', 'Köpeklerin sürekli korku içinde olması'], 'Havlama kurtlarda da bulunan bir ses türüdür ama seyrek kullanılır; evcilleşme ve insanların seçimiyle köpeklerde havlama hem daha sık hem daha çeşitli bağlamlarda kullanılır hâle gelmiştir.'),
  ('Yuvadan dışarı düşen fare yavrularının çıkardığı ve insan kulağının duyamadığı çağrıların işlevi nedir?', 'Annenin yavruyu bulmasını sağlamak', ['Avcıları ürkütmek', 'Kardeşleriyle oyun oynamak', 'Vücut ısısını yükseltmek'], 'Yuvadan uzaklaşıp üşüyen fare yavruları ultrasonik çağrılar çıkarır; anne bu sesleri izleyerek yavruyu bulur ve yuvaya geri taşır.'),
  ('Bir yarasa çıkardığı ses darbesinin yankısını 0,02 saniye sonra duyuyor. Havada sesin hızı 340 m/s alınırsa, sesi yansıtan böcek yarasadan yaklaşık kaç metre uzaktadır?', '3,4', ['6,8', '1,7', '13,6'], 'Ses gidip geri döndüğü için toplam yol 340 × 0,02 = 6,8 m\'dir; böceğe uzaklık bunun yarısı, yani 3,4 metredir.'),
  ('Vombatları diğer memelilerden ayıran ilginç dışkı özelliği hangisidir?', 'Dışkılarının küp biçiminde olması', ['Dışkılarının karanlıkta parlaması', 'Yılda yalnızca bir kez dışkılamaları', 'Dışkılarının tamamen sıvı olması'], 'Vombat bağırsağının son bölümünde duvarın farklı kesimlerinin farklı esneklikte olması, dışkının köşeli küpler hâlinde şekillenmesini sağlar; vombatlar bu küpleri kaya ve kütüklerin üstüne bırakarak koku işareti yapar.'),
  ('Erkek aslanların bir sürünün denetimini ele geçirmek için çoğu zaman kardeş ya da akraba erkeklerle birlikte hareket etmesine ne ad verilir?', 'Erkek koalisyonu', ['Harem düzeni', 'Lek alanı', 'Matriark grubu'], 'Koalisyon hâlindeki erkekler rakip erkeklere karşı daha güçlüdür ve sürüyü daha uzun süre ellerinde tutabilir; tek başına bir erkeğin sürü edinme şansı ise düşüktür.'),
  ('Koatilerin yürürken uzun, halkalı kuyruklarını dik tutmasının olası işlevi nedir?', 'Grup üyelerinin birbirini görmesi', ['Kuyrukla nefes almak', 'Avcıları kuyrukla boğmak', 'Kuyruktan süt vermek'], 'Gruplar hâlinde dolaşan koatilerin dik tuttukları kuyruklar, yoğun çalılıklarda bile birbirlerini izlemelerine yardım eder; kuyruk tırmanırken denge de sağlar.'),
  ('Kokarcanın püskürttüğü sıvının avcılara karşı etkili olmasının başlıca nedeni nedir?', 'Kükürtlü bileşiklerin keskin kokusu', ['Sıvının avcıyı hemen öldüren bir zehir olması', 'Sıvının avcıyı uyutması', 'Sıvının avcının tüylerini döktürmesi'], 'Kokarca salgısındaki tiyol adlı kükürtlü bileşikler çok düşük derişimde bile algılanır; göze geldiğinde geçici yanma ve görme bozukluğu yapar.'),
  ('Bal porsuklarının Afrika\'da arı kovanlarına saldırmasının temel amacı nedir?', 'Arı larvalarını ve balı yemek', ['Kovanın içinde kış uykusuna yatmak', 'Arıları yuvasına taşıyıp evcilleştirmek', 'Kovan mumunu yuvasına taşımak'], 'Bal porsuğu kalın derisi sayesinde arı sokmalarına büyük ölçüde dayanır; kovanları kırarak protein kaynağı olan larvaları ve balı yer.'),
  ('Fillerin büyük ağırlığına rağmen yürürken ses çıkarmadan ilerleyebilmesini sağlayan ayak yapısı hangisidir?', 'Topuktaki yağ yastığı', ['Toynakların içinin boş olması', 'Ayak tabanlarındaki uzun kıllar', 'Ayak parmaklarının perdeli olması'], 'Fil ayağında kemikler hafifçe eğik durur ve topuğun altında süngerimsi kalın bir yağ yastığı bulunur; bu yastık ağırlığı dağıtır, şokları emer ve adımları sessizleştirir.'),
  ('Ters dönmüş hâlde düşen bir kedinin havada dönüp ayakları üstüne inebilmesini sağlayan etkenler hangi seçenekte doğru verilmiştir?', 'Esnek omurga ve denge refleksi', ['Kuyruğundaki hava keseleri', 'Kulaklarını kanat gibi açması', 'Pençelerinden çıkan yapışkan salgı'], 'Kedi iç kulaktaki denge organından aldığı bilgiyle önce başını, sonra gövdesinin ön ve arka yarısını sırayla döndürür; çok esnek omurgası bu dönüşü mümkün kılar.'),
  ('Yavru fil annesini nasıl emer?', 'Ağzıyla, hortumunu kenara kıvırarak', ['Hortumuyla süt çekerek', 'Annesi sütü hortumuyla ağzına akıtarak', 'Yavru ilk yıl hiç emmez'], 'Yavru fil hortumunu yukarı ya da yana kıvırıp annenin ön bacakları arasındaki memeleri ağzıyla emer; hortumunu ustaca kullanmayı ancak aylar içinde öğrenir.'),
  ('Koalalar ağaçlardan nadiren inip su içer. Su ihtiyaçlarının büyük kısmını nasıl karşılarlar?', 'Yedikleri okaliptüs yapraklarındaki sudan', ['Kürklerine biriken yağmur damlalarını emerek', 'Yağ depolarını yakarak', 'Annelerinin sütünü ömür boyu içerek'], 'Koalalar suyun büyük bölümünü nemli okaliptüs yapraklarından alır; ancak sıcak ve kurak dönemlerde ağaçtan inip su içtikleri de gözlenir.'),
  ('Afrika savanlarında fillerin ağaçları devirip kabuklarını soyması bitki örtüsünü nasıl etkiler?', 'Otlakları açık tutar', ['Savanı kısa sürede yağmur ormanına dönüştürür', 'Ot yetişmesini tamamen engeller', 'Hiçbir etkisi yoktur'], 'Filler ağaçların bir bölümünü devirerek savanın ağaçlık ile otlak arasındaki dengesini etkiler; bu yönüyle de birer ekosistem mühendisi sayılır.'),
  ('Halk arasında \'koala ayısı\' denmesine rağmen koala hakkında hangisi doğrudur?', 'Ayı değil, keseli bir memelidir', ['Avustralya\'ya özgü bir ayı türüdür', 'Rakungiller familyasındandır', 'Kemirgenler takımındadır'], 'Koala, vombatlarla akraba keseli bir memelidir; tıknaz görünüşü nedeniyle ayıya benzetilmiştir.'),
  ('Su aygırının adı \'nehir atı\' anlamına gelen Yunanca hippopotamos sözcüğünden gelir. Biyolojik akrabalık açısından bu adın yanıltıcı olmasının nedeni nedir?', 'Su aygırının çift toynaklı olması', ['Su aygırının hiç suya girmemesi', 'Su aygırının keseli olması', 'Su aygırının kemirgen olması'], 'Su aygırı çift toynaklılardandır ve en yakın akrabaları balinalardır; atlar ise tek toynaklılardır.'),
  ('Hortumlular takımının (filler ve soyu tükenmiş akrabaları) en eski fosilleri hangi kıtada bulunmuştur?', 'Afrika', ['Kuzey Amerika', 'Avustralya', 'Güney Amerika'], 'Eosen dönemine ait en eski hortumlu fosilleri Kuzey Afrika\'da bulunmuştur; filler daha sonra Avrasya ve Amerika\'ya yayılmıştır.'),
  ('Yeni Gine ve Avustralya\'nın kuzeydoğusundaki yağmur ormanlarında yaşayan ağaç kangurularını yer kangurularından ayıran uyum hangisidir?', 'Güçlü ön bacaklar ve pençeler', ['Perdeli arka ayaklar', 'Kanat zarları', 'Gövdesini saran dikenler'], 'Ağaç kangurularının ön bacakları yer kangurularınınkinden daha güçlü, arka bacakları ise daha kısadır; uzun kuyrukları dalda denge sağlar.'),
  ('Opossumların kavrayıcı kuyruklarını yuva yaparken nasıl kullandığı gözlenmiştir?', 'Yaprakları kuyrukla taşımak', ['Kuyruğuyla yuvaya su doldurmak', 'Kuyruğunu yuvanın kapısı olarak kullanmak', 'Kuyruğuyla yuvayı kazmak'], 'Opossumlar topladıkları kuru yaprakları kuyruklarıyla kıvırıp sararak yuvalarına taşır; kuyruk ayrıca tırmanırken dala tutunmaya yardım eder.'),
  ('Bozayıların belirli ağaçlara sırtlarını sürtmesi ve bu ağaçların kuşaklar boyu kullanılması hangi iletişim türüne örnektir?', 'Koku yoluyla iletişim', ['Ses yoluyla iletişim', 'Görsel işaretle iletişim', 'Titreşimle iletişim'], 'Ayılar sırtlarını ve boyunlarını sürterek ağaca koku ve kıl bırakır; bu ağaçlar bölgedeki diğer ayılar için bir tür ilan panosu işlevi görür.'),
  ('Kuduz hastalığı hakkında aşağıdakilerden hangisi doğrudur?', 'Memelilere bulaşan bir virüs hastalığıdır', ['Yalnızca köpeklerde görülür', 'Bakterilerle yayılan bir mide hastalığıdır', 'Yalnızca kuşlarda görülür'], 'Kuduz virüsü sinir sistemini etkiler ve memelilerin hepsine bulaşabilir; yabani hayatta tilki, yarasa ve rakun gibi türler önemli taşıyıcılardır.'),
  ('Yabani memelilerden insanlara bulaşan hastalıkların genel adı nedir?', 'Zoonoz', ['Epidemi', 'Mutasyon', 'Simbiyoz'], 'Zoonozlar hayvanlardan insanlara bulaşan hastalıklardır; kuduz ve veba memeli kaynaklı zoonozların bilinen örnekleridir.'),
  ('Afrika fillerinin selamlaşırken hortumlarını birbirlerinin ağzına doğru uzatmasının işlevi nedir?', 'Koku ve tatla tanışmak', ['Birbirine su aktarmak', 'Birbirinin dişlerini temizlemek', 'Vücut ısısı alışverişi yapmak'], 'Filler hortumlarını diğer bireyin ağzına ve yüzüne değdirerek koku ve tat bilgisi alır; bu, aile üyeleri arasında güçlü bir selamlaşma ve tanışma davranışıdır.'),
  ('Bir tavşanın beslenirken çevresini kollaması ve tehlike sezdiğinde \'donup kalması\' hangi stratejinin parçasıdır?', 'Fark edilmemek', ['Avcıyı saldırmaya kışkırtmak', 'Vücut ısısını hızla düşürmek', 'Dağılmış sürüyü bir araya toplamak'], 'Pek çok avcı hareket eden avı daha kolay fark eder; kamuflaj rengine sahip bir tavşanın kımıldamadan durması onu fark edilmekten koruyabilir, avcı çok yaklaşırsa ani bir kaçış başlar.'),
  ('Ormanlarda bir ağacın kabuğunun yerden belirli yükseklikte halka biçiminde soyulduğu, bu nedenle ağacın kuruduğu görülüyor. Kışın besin kıtlığında bu tür hasarı en çok hangi memeliler verir?', 'Geyik ve tavşan gibi otçullar', ['Böcekçil yarasalar', 'Kirpiler ve sivri fareler', 'Köstebekler'], 'Kışın ot bulunmayınca geyikler, tavşanlar ve bazı kemirgenler ağaç kabuğunu kemirir; kabuk halka biçiminde tümüyle soyulursa ağacın iletim dokusu kesilir ve ağaç kurur.'),
  ('Yörük çadırlarının geleneksel olarak dokunduğu, suyu iyi geçirmeyen sert lif hangi hayvandan elde edilir?', 'Kıl keçisi', ['Ankara keçisi', 'Merinos koyunu', 'Ankara tavşanı'], 'Kara (kıl) keçisinin uzun, sert kılları dokunarak çadır yapılır; kıllar ıslandığında şişip aralıkları kapattığı için çadır yağmur geçirmez hâle gelir.'),
  ('Uzun, ipeksi beyaz tüyleri ve çoğu zaman farklı renkteki gözleriyle tanınan, Ankara\'yla özdeşleşmiş kedi ırkı hangisidir?', 'Ankara kedisi', ['Van kedisi', 'İran kedisi', 'Siyam kedisi'], 'Ankara kedisi (Türk Angorası) ince yapılı, uzun tüylü bir ırktır; Van kedisinden farklı olarak çoğunlukla tamamen beyazdır ve suya ilgisiyle bilinmez.'),
  ('Uzun bacakları ve ince, derin göğsüyle hızlı koşmaya uyumlu olan, Anadolu\'da geleneksel olarak tavşan avında kullanılan köpek ırkı hangisidir?', 'Türk tazısı', ['Kangal', 'Akbaş', 'Kars çoban köpeği'], 'Tazılar görerek avlanan, hız için seçilmiş köpeklerdir; Anadolu\'da geleneksel olarak tavşan ve tilki avında kullanılır. Kangal, Akbaş ve Kars köpekleri ise sürü koruma köpekleridir.'),
  ('Kapibara ve su aygırının gözleri, kulakları ve burun deliklerinin başın üst kısmında aynı hizada olmasının ortak yararı nedir?', 'Su altındayken çevreyi izlemek', ['Kara yırtıcılarını daha iyi duymak', 'Ağaç dallarına uzanmak', 'Kumda gizlenmek'], 'Bu yerleşim, hayvanın neredeyse tamamen suya batmışken çevresini izlemesine ve soluk almasına izin verir; akraba olmayan iki türdeki benzerlik yakınsak evrimin örneğidir.'),
  ('Bir öğrenci \'Bütün memeliler karada yaşar\' diyor. Bu yargının yanlış olduğunu gösteren örnekler hangi seçenekte doğru verilmiştir?', 'Yarasalar uçar, balinalar denizdedir', ['Kediler ağaca tırmanır, köpekler yüzer', 'Atlar koşar, inekler otlar', 'Fareler toprakta yuva yapar, tavşanlar sıçrar'], 'Memeliler karanın yanı sıra havada uçan yarasalar ve tamamen denizde yaşayan balinalar gibi çok farklı ortamlara uyum sağlamıştır.'),
  ('Kuzey Amerika\'da \'grizzly\' adıyla bilinen ayı hangi türün bir alt türü ya da yerel biçimidir?', 'Bozayı', ['Kara ayı', 'Kutup ayısı', 'Gözlüklü ayı'], 'Grizzly, Kuzey Amerika\'nın iç kesimlerinde yaşayan bozayılara verilen addır; kıllarının uçlarının açık renkli olması ona kırçıl bir görünüm verir.'),
  ('Amerika kıtasının en büyük kedisi hangisidir?', 'Jaguar', ['Puma', 'Ocelot', 'Kanada vaşağı'], 'Jaguar, Amerika kıtasında yaşayan en iri kedigildir; puma geniş yayılışlı olsa da daha hafif yapılıdır.'),
  ('Erkek kırmızı kangurular dövüşürken rakiplerine nasıl saldırır?', 'Kuyruğa dayanıp tekme atarak', ['Boynuzlarıyla toslaşarak', 'Dişleriyle boyun ısırarak', 'Kuyruklarını kamçı gibi savurarak'], 'Erkek kangurular ön kollarıyla güreşir, kuyruklarına yaslanarak iki arka ayaklarıyla rakiplerinin karnına güçlü tekmeler atar.'),
  ('Su aygırlarının suda nasıl hareket ettiği hakkında hangisi doğrudur?', 'Yüzmez, dipte yürür', ['Balinalar gibi kuyruk yüzgeciyle yüzer', 'Su yüzeyinde sürekli sırtüstü yüzer', 'Kanat çırpar gibi ön ayaklarını kullanır'], 'Su aygırları çok yoğun yapılıdır ve batma eğilimindedir; sığ suda dipte yürür ya da sıçrayarak ilerler, nefes almak için yüzeye çıkar.'),
  ('Fillerin derin suda yüzerken soluk almak için kullandığı yöntem hangisidir?', 'Hortumunu şnorkel gibi suyun üstüne çıkarmak', ['Kulaklarındaki hava ceplerinden yararlanmak', 'Derisinden oksijen almak', 'Su altında hiç soluk almadan saatlerce kalmak'], 'Filler iyi yüzücüdür; gövdeleri batmış hâldeyken hortumlarını suyun üstünde tutarak şnorkel gibi kullanır.'),
  ('Fas\'ta keçilerin argan ağaçlarının dallarına tırmanarak meyve yemesinin ağaç için olası bir yararı hangisidir?', 'Geviş getirirken tohumları tükürerek yaymaları', ['Ağacın dallarını budayıp büyümesini durdurmaları', 'Ağacın köklerini sulamaları', 'Ağacı böceklerden tamamen temizlemeleri'], 'Keçiler argan meyvesini yer ve geviş getirirken sert çekirdekleri tükürür; bu, çekirdeklerin ağaçtan uzaklara taşınmasına yardım edebilir.'),
  ('Teksas\'taki Bracken Mağarası hangi özelliğiyle bilinir?', 'Dev yarasa kolonisiyle', ['Dünyanın en büyük kunduz barajıyla', 'En kalabalık kurt sürüsüyle', 'Kutup ayılarının kışladığı yer olmasıyla'], 'Bracken Mağarası yazın milyonlarca Meksika serbest kuyruklu yarasasına ev sahipliği yapar; bu, bilinen en büyük memeli topluluklarından biridir.'),
  ('Kuzey İskandinavya\'da Sami halkının sürüler hâlinde güttüğü yarı evcil memeli hangisidir?', 'Ren geyiği', ['Sığın', 'Misk öküzü', 'Tibet yakı'], 'Sami halkı yüzyıllardır ren geyiği sürülerini mevsimsel otlaklar arasında güder; ren geyiği et, süt, deri ve taşımacılık için kullanılır.'),
  ('Suriye (altın) hamsterlarının evde tek başına tutulmasının önerilmesinin nedeni nedir?', 'Türdeşlerine saldırgan olmaları', ['Gündüz etkin olmaları', 'Su içmemeleri', 'Kış uykusuna hiç yatmamaları'], 'Suriye hamsterları doğada yalnız yaşar; aynı kafeste tutulan erişkinler sık sık kavga eder ve birbirini yaralayabilir.'),
  ('Kedilerin ağaçtan inerken genellikle geri geri ya da kayarak inmesinin nedeni nedir?', 'Pençelerinin geriye kıvrık olması', ['Kedilerin yükseklik korkusu', 'Arka bacaklarının daha kısa olması', 'Kuyruklarının yere değmesi gerektiği'], 'Kedi pençeleri geriye kıvrıktır; tırmanırken ağaca iyi tutunur ama baş aşağı inerken tutunma sağlamaz. Bu nedenle kediler çoğu zaman geri geri iner.'),
  ('Köpek mamasıyla uzun süre beslenen bir kedide görme ve kalp sorunları ortaya çıkabilir. Bunun nedeni nedir?', 'Taurin eksikliği', ['Köpek mamasının fazla tuzlu olması', 'Kedilerin et sindirememesi', 'Köpek mamasının çok sert olması'], 'Kediler taurin adlı amino asidi vücutlarında yeterince sentezleyemez ve besinle almak zorundadır; köpek mamaları kediler için yeterli taurin içermeyebilir.'),
  ('Çikolatanın köpekler için zehirli olmasının nedeni hangisidir?', 'Teobromini yavaş yıkmaları', ['Şekeri hiç sindirememeleri', 'Çikolatanın dişlerini eritmesi', 'Çikolatanın sütü pıhtılaştırması'], 'Kakaodaki teobromin köpeklerde insanlardan çok daha yavaş yıkılır ve vücutta birikerek kalp ritim bozukluğu, kusma ve nöbetlere yol açabilir; bitter çikolata en tehlikelisidir.'),
  ('Köpeklerin işlevsel ter bezleri vücutlarının neresinde yoğunlaşmıştır?', 'Pati yastıklarında', ['Sırtlarında', 'Kulaklarının içinde', 'Kuyruklarının ucunda'], 'Köpeklerin ekrin ter bezleri başlıca pati yastıklarında bulunur; sıcak havada ıslak pati izleri bırakmaları bu yüzdendir. Ancak serinlemede asıl rolü soluma oynar.'),
];
